export default {
  props: {
    searchValue: {
      type: String,
      default: ""
    }
  },
  components: {
    SnackBar,
    AddExpense,
    ViewExpenses,
    ExpenseDetailsDialog
  },
  mixins: [get_Org_details],
  data() {
    return {
      SnackBarComponent: {},
      tableData: [],
      rowInfo: {},
      tableLoading: false,
      expenseView: false,
      componentCheck: 0,
      fixed: true,
      height: 0,
      expenseDetailsDialog: false,
      selectedExpenseData: null,
      headers: [{
        title: "Expense Name",
        value: "category_id_text",
        sortable: false
      }, {
        title: "Amount",
        value: "amount",
        sortable: false
      }, {
        title: "Created On",
        value: "transaction_created_on",
        sortable: false
      }, {
        title: "Status",
        value: "transaction_status",
        sortable: false
      }, {
        title: "Documents",
        value: "docs",
        sortable: false
      }],
      currentPage: 1,
      totalItems: 0,
      itemsPerPage: 20,
      windowHeight: 0
    };
  },
  computed: {
    filteredItems() {
      if (!this.searchValue) return this.tableData;
      const searchLower = this.searchValue.toLowerCase();
      return this.tableData.filter(item => item.category_id_text.toLowerCase().includes(searchLower) || item.amount.toString().includes(searchLower) || item.transaction_status.toLowerCase().includes(searchLower));
    },
    sortedAndPaginatedItems() {
      // First sort the filtered items
      const sortedItems = this.filteredItems.slice().sort((a, b) => {
        // Default sort by created date (newest first)
        const aValue = a.transaction_created_on ? a.transaction_created_on : 0;
        const bValue = b.transaction_created_on ? b.transaction_created_on : 0;
        return bValue - aValue;
      });

      // Then paginate
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    totalItems() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    visiblePages() {
